class Solution { public int[] findEvenNumbers(int[] digits){int[] available=new int[10];for(int digit:digits)available[digit]++;List<Integer> answer=new ArrayList<>();for(int number=100;number<1000;number+=2){int[] needed=new int[10];for(int value=number;value>0;value/=10)needed[value%10]++;boolean valid=true;for(int digit=0;digit<10;digit++)if(needed[digit]>available[digit])valid=false;if(valid)answer.add(number);}return answer.stream().mapToInt(Integer::intValue).toArray();} }
